{"path": "src/engagement/model.py", "content": """"Estimator."""
import numpy as np
from sklearn.linear_model import LogisticRegression
from sklearn.preprocessing import StandardScaler


class EngagementModel(object):

    def __init__(self, seed, max_iter, regularisation):
        self.scaler = StandardScaler()
        self.estimator = LogisticRegression(
            solver="lbfgs",
            C=float(regularisation),
            max_iter=int(max_iter),
            random_state=int(seed),
        )

    def fit(self, X, y):
        self.estimator.fit(self.scaler.fit_transform(X), y)
        return self

    def score(self, X):
        return self.estimator.predict_proba(self.scaler.transform(X))[:, 1]
